    function growthRequirement(level) { return 50 + (Math.max(1, num(level, 1)) - 1) * 25; }
    function growthState(base) {
      var level = Math.max(1, num(base["等级"], 1));
      var rank = rankLabel(base["位阶"]);
      var rule = RANK_RULES[rank] || RANK_RULES["普通"];
      var requirement = Math.max(1, num(base["升级所需"], growthRequirement(level)));
      var experience = Math.max(0, num(base["经验"], 0));
      var points = Math.max(0, num(base["属性点"], 0));
      if (!rule.next) {
        return { experience: experience, requirement: requirement, points: points, promotion: "已至神话 · 继续积累", ratio: 100, title: "等级与属性已进入神话尺度。" };
      }
      var levelReady = level >= rule.maxLevel;
      var attrReady = STATS.filter(function (stat) { return num(base[stat.valueKey], 0) >= rule.attrCap; }).length;
      var conditionCount = (levelReady ? 1 : 0) + (Math.min(attrReady, 2) >= 2 ? 1 : 0);
      var ratio = clamp(
        (Math.min(level, rule.maxLevel) / rule.maxLevel) * 50 +
        (Math.min(attrReady, 2) / 2) * 50,
        0,
        conditionCount >= 2 ? 96 : 100,
      );
      return {
        experience: experience,
        requirement: requirement,
        points: points,
        promotion: rule.next + " · 等级 " + Math.min(level, rule.maxLevel) + "/" + rule.maxLevel + " · 属性 " + Math.min(attrReady, 2) + "/2 · 待剧情突破",
        ratio: ratio,
        title: "晋升到" + rule.next + "：等级达到" + rule.maxLevel + "，至少两项基础属性达到" + rule.attrCap + "，并完成对应剧情突破。"
      };
    }
