          if (kv.length < 2) return;
          var k = kv[0].trim();
          var v = kv.slice(1).join(":").trim();
          if (k === "姓名") d.name = v.replace(/[|]/g, "");
          else if (k === "别名") d.aliases = v;
          else if (k === "性别") d.gender = v === "男" ? "男" : "女";
          else if (k === "种族") d.race = v;
          else if (k === "身份/职业") d.identity = v.replace(/[|\s]/g, "");
          else if (k === "所属阵营或地点") d.faction = v;
        });
      }
      var appear = /【外貌特征】[:：]\s*([\s\S]*?)。/.exec(text);
      if (appear) {
        appear[1].split(/；/).forEach(function (part) {
          var kv = part.split(/[:：]/);
          if (kv.length >= 2 && NPC_APPEAR_FIELDS.indexOf(kv[0].trim()) >= 0) d.appearance[kv[0].trim()] = kv.slice(1).join(":").trim();
        });
      }
      var body = /【身材特质】[:：]\s*([\s\S]*?)。/.exec(text);
      if (body) {
        body[1].split(/；/).forEach(function (part) {
          var kv = part.split(/[:：]/);
          if (kv.length >= 2 && npcBodyFields(d.gender).indexOf(kv[0].trim()) >= 0) d.body[kv[0].trim()] = kv.slice(1).join(":").trim();
        });
      }
      var persona = /【性格倾向】[:：]\s*([\s\S]*?)。/.exec(text);
      if (persona) {
        persona[1].split(/；/).forEach(function (part) {
          var kv = part.split(/[:：]/);
          if (kv.length < 2) return;
          if (kv[0].trim() === "性格标签") d.personalityTags = kv.slice(1).join(":").split(/[、,，]/).map(function (s) { return s.trim(); }).filter(Boolean).slice(0, NPC_LEN.tags);
          if (kv[0].trim() === "口头禅/说话风格") d.catchphrase = kv.slice(1).join(":").trim();
        });
      }
      var rel = /与玩家初始关系=([^。]+)/.exec(text);
      if (rel && NPC_RELATIONS.indexOf(rel[1]) >= 0) d.relation = rel[1];
      var sens = /六项敏感度（0-10）[:：]([^。]+)/.exec(text);
      if (sens) {
        sens[1].split(/[，,]/).forEach(function (part) {
          var bits = part.trim().split(/\s+/);
          if (bits.length === 2 && npcSensFields(d.gender).indexOf(bits[0]) >= 0) d.sens[bits[0]] = npcClampSens(bits[1]);
        });
      }
      var likes = /偏好[:：]([^。]+)/.exec(text);
      if (likes) d.likes = likes[1].trim();
      var limits = /边界与禁忌（未列出的一律不加）[:：]([^。]+)/.exec(text);
      if (limits) d.limits = limits[1].trim();
      var power = /【实力阶级】[:：]\s*([^。]+)/.exec(text);
      if (power && NPC_POWER.indexOf(power[1].trim()) >= 0) d.power = power[1].trim();
      var bio = /【简要经历】[:：]\s*([\s\S]*?)。/.exec(text);
      if (bio) d.bio = bio[1].trim();
      var gear = /【装备】[:：]\s*([^\n【]*)/.exec(text);
      if (gear) d.gear = parseNpcItemsText(gear[1]);
      var skills = /【技能】[:：]\s*([^\n【]*)/.exec(text);
      if (skills) d.skills = parseNpcItemsText(skills[1]);
      var dev = /六项敏感度（0-10）与开发度（0-100）[:：]([^。]+)/.exec(text);
      if (dev) {
        dev[1].split(/[，,]/).forEach(function (part) {
          var m = /^(\S+)\s*敏感(\d+)\/开发(\d+)$/.exec(part.trim());
          if (m && npcSensFields(d.gender).indexOf(m[1]) >= 0) {
