        if (!eventMap || typeof on !== "function") return;
        var refresh = function () {
          window.setTimeout(function () {
            if (readLatest()) render();
          }, 250);
        };
        window.__ehxRefreshFromMvu = refresh;
        window.addEventListener("message", function (event) {
          if (event && event.data && event.data.type === "edina:mvu-refresh") refresh();
        });
        ["MESSAGE_RECEIVED", "MESSAGE_UPDATED", "MESSAGE_SWIPED", "VARIABLE_UPDATE_ENDED", "VARIABLE_UPDATE_END"].forEach(function (name) {
