      var input = document.createElement("input");
      input.type = "file";
      input.accept = "image/*";
      input.multiple = true;
      input.webkitdirectory = true;
      input.onchange = async function (event) {
        var files = Array.from(event.target.files || []).filter(function (file) {
          return /^image\//i.test(file.type || "");
        });
        if (!files.length) {
          tip("所选文件夹中没有图片");
          return;
        }
        var matched = 0;
        var failed = 0;
        for (var i = 0; i < files.length; i += 1) {
          var name = avatarNameFromFile(files[i]);
          if (!name) continue;
          try {
            var source = await fileToAvatarData(files[i]);
            writeCustomAvatar("relation", name, source);
            matched += 1;
          } catch (e) {
            failed += 1;
          }
        }
        renderRelationPane();
        tip(matched ? "已按文件名设置 " + matched + " 张头像" + (failed ? "，失败 " + failed + " 张" : "") : "没有文件名能匹配世界书角色");
      };
      input.click();
    }
    boot();
  })();</script>
</body>
</html>
