// --- 关系名册规整纯函数（架构 v3 名字键字典，BP-019；ROSTER-RULES 标记供 tools/verify-roster-rules.mjs 抽取做确定性测试） ---
/* ROSTER-RULES-BEGIN */
function edinaIsPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function edinaText(value) {
  return value === undefined || value === null ? '' : String(value);
}

// 进度字段：好感/在场/标签只认针对性路径更新；整对象载荷（重 add / 整 replace）不得改动，防止全量重写回退人物进度。
const EDINA_ROSTER_PROGRESS_FIELDS = ['好感', '在场', '标签'];// 装备/技能数组按「名称」并集：同名条目用新值更新字段，新名称追加；返回新数组，不改输入。
function edinaUnionNamedList(oldList, newList) {
  const base = Array.isArray(oldList) ? oldList.slice() : [];
  (Array.isArray(newList) ? newList : []).forEach((item) => {
    if (!edinaIsPlainObject(item)) return;
    const name = edinaText(item['名称']).trim();
    if (!name) return;
    const idx = base.findIndex((old) => edinaIsPlainObject(old) && edinaText(old['名称']).trim() === name);
    if (idx >= 0) base[idx] = Object.assign({}, base[idx], item);
    else base.push(item);
  });
  return base;
}

function edinaMergeNsfwState(oldState, newState) {
  const out = edinaIsPlainObject(oldState) ? Object.assign({}, oldState) : {};
  if (edinaIsPlainObject(newState)) {
    Object.keys(newState).forEach((key) => {
      const value = edinaText(newState[key]);
      if (value !== '') out[key] = value;
    });
  }
  return out;
}

// 人物对象字段级合并：progressMode='new' 时进度字段取新值，否则保留旧值；
// 描述性标量取最新非空值；装备/技能按名称并集；NSFW状态逐子项合并；头像强制空串（创作权威合同）。
function edinaMergeRosterEntry(oldEntry, newEntry, progressMode) {
  const base = edinaIsPlainObject(oldEntry) ? Object.assign({}, oldEntry) : {};
  if (!edinaIsPlainObject(newEntry)) return base;
  Object.keys(newEntry).forEach((key) => {
    if (key === '头像') { base[key] = ''; return; }
    if (EDINA_ROSTER_PROGRESS_FIELDS.indexOf(key) !== -1) {
      if (progressMode === 'new') base[key] = newEntry[key];
      return;
    }
    if (key === '装备' || key === '技能') { base[key] = edinaUnionNamedList(base[key], newEntry[key]); return; }
    if (key === 'NSFW状态') { base[key] = edinaMergeNsfwState(base[key], newEntry[key]); return; }
    const value = newEntry[key];
    if (value !== undefined && value !== null && value !== '') base[key] = value;
  });
  return base;
}

// 解析方括号路径字面量（真实 CommandInfo 的 args[0] 形状，收据 tmp-mvu-command-shape-*.json）：
// '["关系"]["名册"]["维多利亚"]' → ['关系','名册','维多利亚']；非纯方括号形态（点号/斜杠/空）返回 null，宁可放行也不误改。
function edinaParseBracketPath(pathIn) {
  const raw = edinaText(pathIn).trim();
  if (raw.charAt(0) !== '[') return null;
  const segs = [];
  const seg = /\["((?:[^"\\]|\\.)*)"\]/g;
  let m = seg.exec(raw);
  while (m !== null) { segs.push(m[1]); m = seg.exec(raw); }
  if (segs.length === 0) return null;
  if (raw.replace(/\["(?:[^"\\]|\\.)*"\]/g, '').trim() !== '') return null;
  return segs;
}

// 旧档兼容：索引数组 → 名字键字典。无名条目丢弃（F1）；同名条目字段级合并进最早位置（进度取最早）。
function edinaRosterDict(rosterIn) {
  if (edinaIsPlainObject(rosterIn)) return rosterIn;
  const out = {};
  (Array.isArray(rosterIn) ? rosterIn : []).forEach((entry) => {
    if (!edinaIsPlainObject(entry)) return;
    const name = edinaText(entry['名字']).trim();
    if (!name) return;
    out[name] = out[name] ? edinaMergeRosterEntry(out[name], entry, 'keep') : edinaMergeRosterEntry(null, entry, 'new');
  });
  return out;
}

// 命令级规整（BP-019 v3 字典版；输入模型=真实 CommandInfo，只就地改 args，不 push、不删除命令）。
// 名字键后不再存在索引位移，索引重映射整体退役。本层只做三件事：
//   ① 新建人物：键=名字。模型沿数组习惯写 '-' 时把路径与键改写为真实名字；同名重 add（F2）
//      的值改写为字段级合并后的完整对象（进度保旧值，头像强制空串）；
//   ② 进度字段（好感/在场/标签）定向更新的名字锚定：目标名字未在输出正文出现 → 增量改 0 / 原值写回；
//   ③ 技能/装备子数组追加的名字锚定：未锚定 → 名称置空（应用后归一按无效条目丢弃）。
function edinaRewriteRosterCommands(commands, rosterIn, messageContent) {
  const stats = { scanned: 0, valueRewritten: 0, pathRemapped: 0, guarded: 0 };
  const anchored = (name) => {
    if (!name) return true;
    if (typeof messageContent !== 'string' || messageContent === '') return true;
    return messageContent.indexOf(name) !== -1;
  };
  if (!Array.isArray(commands)) return stats;
  const roster = edinaRosterDict(rosterIn); // 批内工作字典：随本批命令同步更新，保证同批后续合并拿到最新值
  const rebuildPath = (segs) => segs.map((s) => '["' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"]').join('');
  (Array.isArray(commands) ? commands : []).forEach((cmd) => {
    if (!cmd) return;
    const kind = cmd.type;
    if (kind !== 'set' && kind !== 'insert' && kind !== 'add' && kind !== 'delete' && kind !== 'delta') return;
    if (!Array.isArray(cmd.args) || cmd.args.length < 1) return;
    const segs = edinaParseBracketPath(cmd.args[0]);
    if (!segs || segs.length < 2 || segs[0] !== '关系' || segs[1] !== '名册') return;
    stats.scanned += 1;

    const name = edinaText(segs[2]).trim();

    // 新建/追加命令
    if ((kind === 'insert' || kind === 'add') && cmd.args.length >= 3) {
      // 人物整对象新建：args=[册路径(2段), 键字面量, 值字面量]——键在 args[1]，
      // 真实 CommandInfo 形状里 MVU 的 kn 转换把键从路径拆出（收据 tmp-mvu-command-shape-*.json）。
      if (segs.length === 2) {
        let value = null;
        try { value = JSON.parse(cmd.args[2]); } catch (_) { value = null; }
        if (!edinaIsPlainObject(value)) return;
        const entryName = edinaText(value['名字']).trim();
        if (!entryName) return; // F1 无名：照原样放行，应用后归一丢弃
        let keyName = '';
        try { keyName = edinaText(JSON.parse(edinaText(cmd.args[1]).trim())).trim(); } catch (_) { keyName = ''; }
        if (keyName !== entryName) {
          // 模型写 '-'（旧数组习惯）或键名与对象名字不一致 → 以对象名字为准改写键
          cmd.args[1] = JSON.stringify(entryName);
          stats.pathRemapped += 1;
        }
        if (roster[entryName]) {
          // F2 同名重 add：值改写为字段级合并后的完整对象，防止 zod 缺字段填默认造成"清空"
          const merged = edinaMergeRosterEntry(roster[entryName], value, 'keep');
          merged['头像'] = '';
          cmd.args[2] = JSON.stringify(merged);
          roster[entryName] = merged;
          stats.valueRewritten += 1;
        } else {
          roster[entryName] = edinaMergeRosterEntry(null, value, 'new');
        }
        return;
      }
      // 技能/装备子数组追加：args=[人物子路径(4段,含名字), '"-"', 条目值]；名字锚定不通过时把名称置空
      if (segs.length === 4 && (segs[3] === '装备' || segs[3] === '技能')) {
        if (edinaText(cmd.args[1]).trim() !== '"-"') return;
        if (!anchored(name)) {
          try {
            const item = JSON.parse(cmd.args[2]);
            if (edinaIsPlainObject(item) && edinaText(item['名称']).trim() !== '') {
              item['名称'] = '';
              cmd.args[2] = JSON.stringify(item);
              stats.guarded += 1;
            }
          } catch (_) {}
        }
        return;
      }
      return;
    }

    // 整册操作（其余类型）：不建模，应用后归一兜底
    if (segs.length === 2) return;

    // 整条目删除：按名字删，无位移，放行
    if (kind === 'delete' && segs.length === 3) return;

    // delta（数值增量）：进度字段的名字锚定不通过 → 增量改写为 0（无操作）
    if (kind === 'delta' && segs.length === 4) {
      if (EDINA_ROSTER_PROGRESS_FIELDS.indexOf(segs[3]) !== -1 && !anchored(name)) {
        cmd.args[1] = '0';
        stats.guarded += 1;
      }
      return;
    }

    if (kind !== 'set') return;
    // 进度字段整写：名字锚定不通过 → 原值写回（无操作），防止好感等进度被写到别人头上
    if (segs.length === 4 && EDINA_ROSTER_PROGRESS_FIELDS.indexOf(segs[3]) !== -1 && !anchored(name)) {
      let value = null;
      try { value = JSON.parse(cmd.args[1]); } catch (_) { value = null; }
      cmd.args[1] = JSON.stringify(roster[name] ? roster[name][segs[3]] : value);
      stats.guarded += 1;
      return;
    }
    // 整条目 set：值改写为字段级合并后的完整对象，防止 zod 把缺字段填成默认值造成"清空"假象
    if (segs.length === 3 && roster[name]) {
      let value = null;
      try { value = JSON.parse(cmd.args[1]); } catch (_) { value = null; }
      if (!edinaIsPlainObject(value)) return;
      const merged = edinaMergeRosterEntry(roster[name], value, 'keep');
      merged['头像'] = '';
      cmd.args[1] = JSON.stringify(merged);
      roster[name] = merged;
      stats.valueRewritten += 1;
      return;
    }
    // 子字段更新：同步进批内模拟，保证同批后续整对象合并拿到最新值
    if (segs.length === 4 && roster[name] && edinaIsPlainObject(roster[name])) {
      let value = null;
      try { value = JSON.parse(cmd.args[1]); } catch (_) { value = null; }
      if (value !== null && value !== undefined) roster[name][segs[3]] = value;
    }
  });
  return stats;
}

// 旧档自动迁移（BP-019 v3，驾驶员 2026-09-26 批准）：索引数组 → 名字键字典。
// 先按旧规则对数组去重合并（进度取最早），再按键=名字落字典；无名条目丢弃；头像强制空串。
function edinaDedupeRoster(rosterIn) {
  if (!Array.isArray(rosterIn)) return { roster: rosterIn, changed: false, removed: 0 };
  const roster = rosterIn.slice();
  const groups = {};
  roster.forEach((entry, i) => {
    if (!edinaIsPlainObject(entry)) return;
    const name = edinaText(entry['名字']).trim();
    if (!name) return;
    if (!groups[name]) groups[name] = [];
    groups[name].push(i);
  });
  const removals = [];
  let changed = false;
  Object.keys(groups).forEach((name) => {
    const idxs = groups[name];
    if (idxs.length < 2) return;
    let merged = roster[idxs[0]];
    for (let k = 1; k < idxs.length; k++) merged = edinaMergeRosterEntry(merged, roster[idxs[k]], 'keep');
    if (JSON.stringify(merged) !== JSON.stringify(roster[idxs[0]])) changed = true;
    roster[idxs[0]] = merged;
    for (let k = 1; k < idxs.length; k++) removals.push(idxs[k]);
  });
  removals.sort((a, b) => b - a).forEach((i) => roster.splice(i, 1));
  if (removals.length > 0) changed = true;
  return { roster, changed, removed: removals.length };
}

function edinaMigrateRoster(rosterIn) {
  if (!Array.isArray(rosterIn)) return rosterIn;
  const deduped = edinaDedupeRoster(rosterIn).roster;
  const out = {};
  deduped.forEach((entry) => {
    if (!edinaIsPlainObject(entry)) return;
    const name = edinaText(entry['名字']).trim();
    if (!name || out[name]) return;
    entry['头像'] = '';
    out[name] = entry;
  });
  return out;
}

// 应用后归一（BP-019 v3 字典版）：键即名字——
// ① 无名/非对象/'-' 占位键丢弃（F1）；② 键与「名字」字段不一致时以键为准补写名字；
// ③ 按快照做字段级恢复：模型整对象重写丢掉的字段补回来；④ 技能/装备无效条目清理；⑤ 头像强制空串。
// 字典键天然唯一，同名合并在键层面不存在。返回新对象，不改输入。
function edinaNormalizeRosterAfterUpdate(rosterIn, previousIn) {
  if (Array.isArray(rosterIn) || !edinaIsPlainObject(rosterIn)) {
    return { roster: rosterIn, changed: false, dropped: 0, merged: 0, restored: 0 };
  }
  const previousByName = edinaRosterDict(previousIn);
  const out = {};
  let dropped = 0;
  let restored = 0;
  Object.keys(rosterIn).forEach((key) => {
    const entry = rosterIn[key];
    if (key.charAt(0) === '$') { out[key] = entry; return; } // $meta 等元数据键直通
    if (!edinaIsPlainObject(entry)) { dropped += 1; return; }
    // 键即真源：名字以键为准；占位键（'-' 等数组习惯）才回落到对象自己的「名字」字段
    const entryName = edinaText(entry['名字']).trim();
    const keyName = edinaText(key).trim();
    let name = keyName && keyName !== '-' ? keyName : entryName;
    if (!name || out[name]) { dropped += 1; return; }
    let merged = entry;
    const previous = previousByName[name];
    if (previous) {
      const lostField = Object.keys(previous).some((k) => {
        if (k === '名字' || k === '头像') return false;
        return edinaText(previous[k]) !== '' && edinaText(entry[k]) === '';
      });
      const before = JSON.stringify(entry);
      merged = edinaMergeRosterEntry(previous, entry, lostField ? 'keep' : 'new');
      if (JSON.stringify(merged) !== before) restored += 1;
    }
    // 无效数组项清理：技能/装备条目必须有非空名称（命令层锚定中和的误插条目在这里落盘前被丢弃）
    ['装备', '技能'].forEach((listKey) => {
      const list = merged[listKey];
      if (!Array.isArray(list)) return;
      const filtered = list.filter((item) => (edinaIsPlainObject(item) ? edinaText(item['名称']).trim() : edinaText(item).trim()) !== '');
      if (filtered.length !== list.length) {
        if (merged === entry) merged = Object.assign({}, merged);
        merged[listKey] = filtered;
      }
    });
    if (merged === entry) merged = Object.assign({}, entry);
    merged['头像'] = '';
    merged['名字'] = name; // 键即名字：以键为准补写，防止模型只改对象不认识键
    out[name] = merged;
  });
  const changed = JSON.stringify(rosterIn) !== JSON.stringify(out);
  return { roster: out, changed, dropped, merged: 0, restored };
}
/* ROSTER-RULES-END */

// --- 关系名册规整接入层（BP-019 v3 名字键字典；接入点由真机实测定案，见 BLUEPRINT §2.1 与收据 tmp-mvu-command-shape-*.json） ---
// MVU 事件是多参数签名：COMMAND_PARSED(variables, commands, message_content)、
// VARIABLE_UPDATE_ENDED(variables, variables_before_update)。命令在第二个参数上；ENDED 第二参数就是应用前快照。
// 实测事件序列：mag_command_parsed → mag_command_parsed_for_zod（schema 校验预应用）→ 应用命令 → mag_variable_update_ended，
// 所以在 COMMAND_PARSED 里同步改 args 天然先于 zod 校验；在 ENDED 里就地改载荷，随后落盘的就是改后的值。
// 两层职责（单轨，无 replaceMvuData 直写，无抢写与事件回环）：
// ① 命令级 edinaRewriteRosterCommands：同名重 add/整条目 set 的值改写为字段级合并后的完整对象 + '-' 占位键改写为名字键；
// ② 应用后 edinaNormalizeRosterAfterUpdate：F1 无名丢弃、键=名字补写、丢字段按快照恢复、头像强制空串。
// 双写防护（验收缺口 G2）：命中计数暴露在 __EDINA_ROSTER_STATS__，真机探针断言每轮命中符合预期。
(function bindRosterNormalize() {
  const stats = { commandRewritten: 0, pathRemapped: 0, guarded: 0, dropped: 0, merged: 0, restored: 0, lastAt: 0 };
  const publishStats = () => {
    let snapshot = null;
    try { snapshot = JSON.parse(JSON.stringify(stats)); } catch (_) { return; }
    try { window.__EDINA_ROSTER_STATS__ = snapshot; } catch (_) {}
    try {
      const parent = window.parent && window.parent !== window ? window.parent : null;
      if (parent) parent.__EDINA_ROSTER_STATS__ = snapshot;
    } catch (_) {}
  };
  const tryBind = () => {
    const scope = typeof eventOn === "function" ? window : (window.parent && typeof window.parent.eventOn === "function" ? window.parent : null);
    const api = window.Mvu || (window.parent && window.parent.Mvu);
    if (!(api && api.events && scope && typeof scope.eventOn === "function")) return false;

    const rosterOf = (payload) => {
      try {
        const roster = payload && payload.stat_data && payload.stat_data.关系 && payload.stat_data.关系.名册;
        return (Array.isArray(roster) || (roster && typeof roster === 'object')) ? roster : null;
      } catch (_) { return null; }
    };
    const first = (event, listener) => {
      if (typeof scope.eventMakeFirst === "function") { scope.eventMakeFirst(event, listener); return; }
      scope.eventOn(event, listener);
    };

    // 第一层：命令级改值（命令在第二个参数、正文在第三个；只就地改 args，不 push、不删除命令对象）
    first(api.events.COMMAND_PARSED, (variables, commands, messageContent) => {
      try {
        const hit = edinaRewriteRosterCommands(commands, rosterOf(variables), typeof messageContent === 'string' ? messageContent : '');
        if (hit.valueRewritten || hit.pathRemapped || hit.guarded) {
          stats.commandRewritten += hit.valueRewritten;
          stats.pathRemapped += hit.pathRemapped;
          stats.guarded += hit.guarded;
          stats.lastAt = Date.now();
          publishStats();
          console.info('[艾迪娜名册] 命令级规整：合并改写 ' + hit.valueRewritten + ' 条、路径改写 ' + hit.pathRemapped + ' 条、锚定中和 ' + hit.guarded + ' 条');
        }
      } catch (err) {
        console.error('[艾迪娜名册] 命令级规整失败:', err);
      }
    });

    // 第二层：应用后就地归一（第二参数=应用前快照，不需要自己缓存）。旧档数组交给迁移器，这里只处理字典。
    scope.eventOn(api.events.VARIABLE_UPDATE_ENDED, (variables, variablesBefore) => {
      try {
        const roster = rosterOf(variables);
        if (!roster || Array.isArray(roster)) return;
        const result = edinaNormalizeRosterAfterUpdate(roster, rosterOf(variablesBefore));
        if (!result.changed) return;
        Object.keys(roster).forEach((key) => { delete roster[key]; }); // 就地：保持对象身份，随后落盘的就是规整结果
        Object.assign(roster, result.roster);
        stats.dropped += result.dropped;
        stats.merged += result.merged;
        stats.restored += result.restored;
        stats.lastAt = Date.now();
        publishStats();
        console.info('[艾迪娜名册] 应用后归一：丢弃 ' + result.dropped + ' 条、补回 ' + result.restored + ' 条的缺失字段');
      } catch (err) {
        console.error('[艾迪娜名册] 应用后归一失败:', err);
      }
    });
    return true;
  };
  // 绑定幂等重试（2026-09-21 真机实测）：出现过"信标已就绪但监听未生效"的瞬态（守则第 3 条 iframe
  // 重注册时序敏感）。eventOn/eventMakeFirst 均幂等（已注册则静默无效），因此首次成功后再补注册
  // 4 次（每秒一次）自愈竞态，然后停表；不永久轮询。
  let bindHits = 0;
  const timer = setInterval(() => {
    if (!tryBind()) return;
    bindHits += 1;
    if (bindHits >= 5) clearInterval(timer);
  }, 1000);
})();

// --- 状态栏锚点自愈（方案 B：锚点唯一真源＝MVU 运行时） ---
// 权威依据：青空莉教程《酒馆助手界面: 显示和允许玩家修改变量》写明 “MVU … 自动在回复末尾附加
// <StatusPlaceHolderImpl/>”；MVU 源码（pinned dd4f1d92）实测在助手消息缺该占位符时补 "\n\n<StatusPlaceHolderImpl/>"。
// 因此卡侧不再要求模型输出自定义锚点：这里只在 MVU 万一没附加时补一个 MVU 原生占位符，
// 并顺手清掉模型习惯性写出的旧卡侧锚点，避免它裸露成正文文本。不覆盖预设标签，不改正文和变量。
/* HUD-ANCHOR-RULES-BEGIN */
const EDINA_HUD_ANCHOR = "<StatusPlaceHolderImpl/>";
const EDINA_LEGACY_HUD_ANCHOR = "<EdinaHUDPlaceholder/>";

function edinaEnsureHudAnchorText(message) {
  const source = typeof message === "string" ? message : "";
  if (!source.trim()) return { text: source, changed: false, reason: "empty" };
  if (/<EdinaOpening\s*\/>/i.test(source)) return { text: source, changed: false, reason: "opening" };
  const anchorRe = /<StatusPlaceHolderImpl\s*\/>/gi;
  const legacyRe = /<EdinaHUDPlaceholder\s*\/>/gi;
  const anchorCount = (source.match(anchorRe) || []).length;
  const legacyCount = (source.match(legacyRe) || []).length;
  const trimmed = source.replace(/\s+$/, "");
  if (anchorCount === 1 && legacyCount === 0 && trimmed.endsWith(EDINA_HUD_ANCHOR)) {
    return { text: source, changed: false, reason: "present" };
  }
  const body = source.replace(anchorRe, "").replace(legacyRe, "").replace(/\s+$/, "");
  return {
    text: body ? body + "\n" + EDINA_HUD_ANCHOR : EDINA_HUD_ANCHOR,
    changed: true,
    reason: legacyCount > 0 ? "normalized-legacy" : "appended",
  };
}
/* HUD-ANCHOR-RULES-END */

(function bindHudAnchorFallback() {
  const stats = {
    appended: 0,
    skippedPresent: 0,
    skippedOpening: 0,
    skippedEmpty: 0,
    failed: 0,
    lastMessageId: null,
    lastAt: 0,
    lastReason: "",
  };
  const publishStats = () => {
    let snapshot = null;
    try { snapshot = JSON.parse(JSON.stringify(stats)); } catch (_) { return; }
    try { window.__EDINA_HUD_ANCHOR_STATS__ = snapshot; } catch (_) {}
    try {
      const parent = window.parent && window.parent !== window ? window.parent : null;
      if (parent) parent.__EDINA_HUD_ANCHOR_STATS__ = snapshot;
    } catch (_) {}
  };
  const hostOf = () => {
    try { return (window.parent && window.parent.SillyTavern) || (typeof SillyTavern !== "undefined" ? SillyTavern : null); } catch (_) { return null; }
  };
  const messageApiOf = () => {
    try {
      if (typeof getChatMessages === "function" && typeof setChatMessages === "function") return window;
      const parent = window.parent && window.parent !== window ? window.parent : null;
      if (parent && typeof parent.getChatMessages === "function" && typeof parent.setChatMessages === "function") return parent;
    } catch (_) {}
    return null;
  };
  const latestAssistantId = () => {
    try {
      const context = hostOf() && typeof hostOf().getContext === "function" ? hostOf().getContext() : null;
      const chat = context && Array.isArray(context.chat) ? context.chat : [];
      for (let i = chat.length - 1; i >= 0; i -= 1) {
        if (chat[i] && !chat[i].is_user && !chat[i].is_system) return i;
      }
    } catch (_) {}
    return null;
  };
  const markSkipped = (reason) => {
    if (reason === "present") stats.skippedPresent += 1;
    else if (reason === "opening") stats.skippedOpening += 1;
    else if (reason === "empty") stats.skippedEmpty += 1;
    stats.lastReason = reason || "";
    stats.lastAt = Date.now();
    publishStats();
  };
  const ensureMessage = async (messageId, reason, attempts) => {
    const api = messageApiOf();
    const numericId = Number(messageId);
    if (!api || !Number.isInteger(numericId) || numericId < 0) {
      stats.failed += 1;
      stats.lastReason = "api-unavailable";
      stats.lastAt = Date.now();
      publishStats();
      return;
    }
    try {
      const message = api.getChatMessages(numericId, { role: "assistant" })[0];
      if (!message || typeof message.message !== "string") {
        if (attempts > 0) setTimeout(() => { void ensureMessage(numericId, reason, attempts - 1); }, 300);
        return;
      }
      const result = edinaEnsureHudAnchorText(message.message);
      stats.lastMessageId = numericId;
      stats.lastReason = result.reason;
      stats.lastAt = Date.now();
      if (!result.changed) {
        markSkipped(result.reason);
        return;
      }
      await api.setChatMessages([{ message_id: numericId, message: result.text }], { refresh: "affected" });
      stats.appended += 1;
      publishStats();
      console.info("[艾迪娜状态栏] 已为消息 #" + numericId + " 补上 MVU 状态栏占位符（" + reason + "）");
      if (reason !== "verify") {
        setTimeout(() => { void ensureMessage(numericId, "verify", 1); }, 350);
      }
    } catch (err) {
      stats.failed += 1;
      stats.lastReason = "failed";
      stats.lastAt = Date.now();
      publishStats();
      console.warn("[艾迪娜状态栏] 锚点自愈失败:", err);
    }
  };
  const ensureLatest = () => {
    const messageId = latestAssistantId();
    if (messageId !== null && messageId !== undefined) void ensureMessage(messageId, "startup", 2);
  };
  const tryBind = () => {
    const scope = typeof eventOn === "function" ? window : (window.parent && typeof window.parent.eventOn === "function" ? window.parent : null);
    const events = (typeof tavern_events !== "undefined" && tavern_events) || (window.parent && window.parent.tavern_events) || {};
    if (!(scope && typeof scope.eventOn === "function" && events.MESSAGE_RECEIVED)) return false;
    const listener = (messageId) => { void ensureMessage(messageId, "received", 3); };
    if (typeof scope.eventMakeFirst === "function") scope.eventMakeFirst(events.MESSAGE_RECEIVED, listener);
    else scope.eventOn(events.MESSAGE_RECEIVED, listener);
    setTimeout(ensureLatest, 1500);
    return true;
  };
  const timer = setInterval(() => {
    if (tryBind()) clearInterval(timer);
  }, 1000);
})();

