// --- 随AI输出模式漏块检测（防呆：模型漏输出变量块或输出空结构时，给玩家可见警告） ---
// 只检测、不代写：警告提示重 Roll 本楼或切额外模型解析。每个楼层只警告一次；开局楼与生成中不检。
(function bindMissingBlockDetector() {
  const warned = new Set();
  let chatKey = "";
  const tryBind = () => {
    const scope = typeof eventOn === "function" ? window : (window.parent && typeof window.parent.eventOn === "function" ? window.parent : null);
