// --- 世界书事件任务诊断（BP-021 / BP-029） ---
// NO-SILENT-WRITE：这里只检查“激活的事件是否已在消息变量中建任务”。
// 绝不调用 replaceMvuData，也不代模型新增任务；唯一任务写入者是主模型或额外模型。
/* EVENT-TASK-RULES-BEGIN */
function edinaTaskMatchLength(value) {
  return Array.from(String(value || '').trim()).length;
}

function edinaTaskMatchKeysForRegistry(keys) {
  const list = Array.isArray(keys) ? keys.map((key) => String(key || '').trim()).filter(Boolean) : [];
  const strong = list.filter((key) => edinaTaskMatchLength(key) >= 4);
  if (strong.length) return [...new Set(strong)];
  return list
    .slice()
    .sort((left, right) => edinaTaskMatchLength(right) - edinaTaskMatchLength(left))
    .slice(0, 1);
}

function edinaVisibleEventText(value) {
  return String(value || '')
    .replace(/<thinking\b[^>]*>[\s\S]*?<\/thinking>/gi, '')
    .replace(/<think\b[^>]*>[\s\S]*?<\/think>/gi, '')
    .replace(/<UpdateVariable\b[^>]*>[\s\S]*?<\/UpdateVariable>/gi, '')
    .replace(/<EdinaTaskEvent\b[^>]*>[\s\S]*?<\/EdinaTaskEvent>/gi, '')
    .replace(/<EdinaBattleSnapshot\b[^>]*>[\s\S]*?<\/EdinaBattleSnapshot>/gi, '')
    .replace(/<EdinaBattleAction\b[^>]*>[\s\S]*?<\/EdinaBattleAction>/gi, '')
    .replace(/<StatusPlaceHolderImpl\s*\/>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '');
}

function edinaEventTaskGroupMatches(group, text) {
  const primary = (Array.isArray(group && group.primary) ? group.primary : [])
    .map((key) => String(key || '').trim())
    .filter(Boolean);
  const secondary = (Array.isArray(group && group.secondary) ? group.secondary : [])
    .map((key) => String(key || '').trim())
    .filter(Boolean);
  if (secondary.length) {
    return primary.some((key) => text.includes(key)) && secondary.some((key) => text.includes(key));
  }
  return edinaTaskMatchKeysForRegistry(primary).some((key) => key && text.includes(key));
}

function edinaEventTaskMatches(meta, currentText) {
  const text = edinaVisibleEventText(currentText);
  const title = String((meta && meta.title) || '').trim();
  if (title && text.includes(title)) return true;
  const groups = Array.isArray(meta && meta.groups) ? meta.groups : [];
  if (groups.length) return groups.some((group) => edinaEventTaskGroupMatches(group, text));
  const keys = Array.isArray(meta && meta.taskKeys)
    ? meta.taskKeys
    : edinaTaskMatchKeysForRegistry(meta && meta.keys);
  return keys.some((key) => key && text.includes(key));
}
/* EVENT-TASK-RULES-END */

(function bindEventTaskBridge() {
  const registry = new Map(EDINA_EVENT_TASKS.map((meta) => [String(meta.uid), meta]));
  const childRegistry = new Map();
  EDINA_EVENT_TASKS.forEach((meta) => {
    (Array.isArray(meta.groups) ? meta.groups : []).forEach((group) => {
      if (group && group.childUid !== undefined && group.childUid !== null) {
        childRegistry.set(String(group.childUid), { meta, kind: group.childKind || meta.kind });
      }
    });
  });
  const pending = new Map();
  const stats = { detected: 0, present: 0, missing: 0, lastAt: 0, lastKeys: [] };
  const publishStats = () => {
    const snapshot = { ...stats, mode: 'diagnostic-only', lastKeys: stats.lastKeys.slice() };
    try { window.__EDINA_EVENT_TASK_STATS__ = snapshot; } catch (_) {}
    try {
      const parent = window.parent && window.parent !== window ? window.parent : null;
      if (parent) parent.__EDINA_EVENT_TASK_STATS__ = snapshot;
    } catch (_) {}
  };
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const hostOf = () => {
    try { return (window.parent && window.parent.SillyTavern) || (typeof SillyTavern !== 'undefined' ? SillyTavern : null); } catch (_) { return null; }
  };
  const apiOf = () => {
    try { return window.Mvu || (window.parent && window.parent.Mvu) || null; } catch (_) { return null; }
  };
  const contextOf = () => {
    const host = hostOf();
    try { return host && typeof host.getContext === 'function' ? host.getContext() : null; } catch (_) { return null; }
  };
  const chatIdOf = () => {
    const context = contextOf();
    return context && typeof context.chatId === 'string' ? context.chatId : '';
  };
  const eventMetaOf = (entry) => {
    const uid = String((entry && (entry.uid ?? entry.id)) ?? '');
    const direct = registry.get(uid);
    if (direct) return direct;
    const child = childRegistry.get(uid);
    const meta = child ? { ...child.meta, kind: child.kind } : null;
    if (!meta) return null;
    return meta;
  };
  const applyPending = async () => {
    const context = contextOf();
    if (!context || !Array.isArray(context.chat) || context.chat.length < 1) return;
    const chatId = String(context.chatId || '');
    const queued = pending.get(chatId);
    if (!queued || queued.size === 0) return;
    const latest = context.chat[context.chat.length - 1];
    if (!latest || latest.is_user) return;
    const api = apiOf();
    if (!api || typeof api.getMvuData !== 'function') return;
    const option = { type: 'message', message_id: 'latest' };
    let data = null;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        data = api.getMvuData(option);
        if (data && data.stat_data && data.stat_data.任务) break;
      } catch (_) {}
      await sleep(500);
    }
    if (!data || !data.stat_data || !data.stat_data.任务) return;
    const tasks = data.stat_data.任务;
    const nsfwEnabled = !data.stat_data.设置 || data.stat_data.设置.NSFW事件 !== false;
    const regularEnabled = !data.stat_data.设置 || data.stat_data.设置.常规事件 !== false;
    const recentUser = [...context.chat].reverse().find((message) => message && message.is_user);
    const currentText = `${edinaVisibleEventText(recentUser?.mes)}\n${edinaVisibleEventText(latest.mes)}`;
    const missing = [];
    for (const meta of queued.values()) {
      const key = `event_${meta.uid}`;
      if (meta.kind === 'NSFW事件' && !nsfwEnabled) continue;
      if (meta.kind === '常规事件' && !regularEnabled) continue;
      const named = edinaEventTaskMatches(meta, currentText);
      if (!named) continue;
      stats.detected += 1;
      if (tasks[key]) {
        stats.present += 1;
      } else {
        stats.missing += 1;
        missing.push(key);
      }
    }
    pending.delete(chatId);
    stats.lastAt = Date.now();
    stats.lastKeys = [...new Set(missing)];
    publishStats();
    if (missing.length) {
      console.warn('[艾迪娜事件] 检测到事件任务缺失，未静默补写，请重 Roll 或切额外模型解析：' + [...new Set(missing)].join(', '));
    }
  };
  const onActivated = (entries) => {
    const list = Array.isArray(entries) ? entries : [];
    const matched = list.map(eventMetaOf).filter(Boolean);
    if (!matched.length) return;
    const chatId = chatIdOf();
    if (!chatId) return;
    const queued = pending.get(chatId) || new Map();
    matched.forEach((meta) => queued.set(`event_${meta.uid}`, meta));
    pending.set(chatId, queued);
  };
  const tryBind = () => {
    const scope = typeof eventOn === 'function' ? window : (window.parent && typeof window.parent.eventOn === 'function' ? window.parent : null);
    if (!(scope && typeof scope.eventOn === 'function')) return false;
    if (typeof tavern_events !== 'object' || !tavern_events) return false;
    if (typeof tavern_events.WORLD_INFO_ACTIVATED !== 'string' || typeof tavern_events.MESSAGE_RECEIVED !== 'string') return false;
    scope.eventOn(tavern_events.WORLD_INFO_ACTIVATED, onActivated);
    scope.eventOn(tavern_events.MESSAGE_RECEIVED, () => setTimeout(applyPending, 1600));
    if (typeof tavern_events.CHAT_CHANGED === 'string') scope.eventOn(tavern_events.CHAT_CHANGED, () => pending.clear());
    if (typeof tavern_events.GENERATION_STOPPED === 'string') scope.eventOn(tavern_events.GENERATION_STOPPED, () => pending.clear());
    publishStats();
    return true;
  };
  let bindAttempts = 0;
  const timer = setInterval(() => {
    bindAttempts += 1;
    if (tryBind() || bindAttempts >= 15) {
      clearInterval(timer);
      if (bindAttempts >= 15) console.warn('[艾迪娜事件] 宿主未提供 WORLD_INFO_ACTIVATED，事件任务诊断未启用。');
    }
  }, 1000);
})();

/* UPDATE-FENCE-RULES-BEGIN */
function edinaFindJsonArrayEnd(text, start) {
  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let i = start; i < text.length; i += 1) {
    const ch = text[i];
    if (quoted) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') quoted = false;
      continue;
    }
    if (ch === '"') { quoted = true; continue; }
    if (ch === '[') depth += 1;
    else if (ch === ']') {
      depth -= 1;
      if (depth === 0) return i + 1;
    }
  }
  return -1;
}

// 真实故障 2026-09-29：模型在合法 JSON 数组后漏写 </JSONPatch>，直接写 </UpdateVariable>，
// 导致整楼补丁不应用。只在数组可被 JSON.parse 成数组时补闭合标签；不改写数组内容，
// 也不接受缺数组、坏 JSON 或多个变量块。
function edinaRepairMissingJsonPatchClose(message) {
  const source = typeof message === 'string' ? message : '';
  if (!source.includes('<JSONPatch')) return { text: source, changed: false };
  let changed = false;
  const text = source.replace(/<UpdateVariable\b[^>]*>[\s\S]*?<\/UpdateVariable>/gi, (block) => {
    if (/<JSONPatch\b[^>]*>[\s\S]*?<\/JSONPatch>/i.test(block)) return block;
    const open = /<JSONPatch\b[^>]*>/i.exec(block);
    if (!open) return block;
    const arrayStart = block.indexOf('[', open.index + open[0].length);
    if (arrayStart < 0) return block;
    const arrayEnd = edinaFindJsonArrayEnd(block, arrayStart);
    if (arrayEnd < 0) return block;
    const candidate = block.slice(arrayStart, arrayEnd);
    try {
      if (!Array.isArray(JSON.parse(candidate))) return block;
    } catch (_) {
      return block;
    }
    const close = block.slice(arrayEnd).search(/<\/UpdateVariable\b/i);
    if (close < 0) return block;
    changed = true;
    return block.slice(0, arrayEnd) + '\n</JSONPatch>' + block.slice(arrayEnd);
  });
  return { text, changed };
}

(function publishUpdateFenceProbe() {
  if (typeof window === 'undefined') return;
  try {
    const sample = [
      '<UpdateVariable>',
      '<Analysis>x</Analysis>',
      '<JSONPatch>',
      '[{"op":"replace","path":"/基础/经验","value":5}]',
      '</UpdateVariable>',
    ].join('\n');
    const result = edinaRepairMissingJsonPatchClose(sample);
    const probe = {
      ok: result.changed && result.text.includes(']\n</JSONPatch>\n</UpdateVariable>'),
      version: 1,
      at: Date.now(),
    };
    window.__EDINA_UPDATE_FENCE_PROBE__ = probe;
    if (window.parent && window.parent !== window) window.parent.__EDINA_UPDATE_FENCE_PROBE__ = probe;
  } catch (err) {
    console.warn('[艾迪娜 MVU] 变量闭合自检失败:', err);
  }
})();
/* UPDATE-FENCE-RULES-END */

// --- 伪变量标签中和（真实故障 2026-09-27：模型在 thinking 中写了一个 OpenTag，
//     但只在最后输出真正的完整变量块；MVU 会从第一个标签开始解析，导致后半个块被错位吞掉）。 ---
// 先在唯一完整块内补齐漏写的 </JSONPatch>；再只处理“多个 OpenTag、但只有一个完整闭合块”。
// 不拼接、不代写 JSONPatch，只保证 MVU 能看到正确的唯一边界。
(function bindAmbiguousUpdateTagGuard() {
  const guard = (text) => String(text || '').replace(/<\/?UpdateVariable\b[^>]*>/gi, (tag) => tag.replace('<', '&lt;').replace('>', '&gt;'));
  const sanitize = () => {
    try {
      const host = (window.parent && window.parent.SillyTavern) || (typeof SillyTavern !== 'undefined' ? SillyTavern : null);
      if (!host || typeof host.getContext !== 'function') return;
      const context = host.getContext();
      if (!context || !Array.isArray(context.chat) || context.isGenerating) return;
      const index = context.chat.length - 1;
      const message = context.chat[index];
      if (!message || message.is_user) return;
      const raw = String(message.mes || '');
      const repaired = edinaRepairMissingJsonPatchClose(raw);
      let next = repaired.text;
      const complete = [...next.matchAll(/<UpdateVariable\b[^>]*>[\s\S]*?<\/UpdateVariable>/gi)];
      const openCount = (next.match(/<UpdateVariable\b/gi) || []).length;
      if (complete.length === 1 && openCount > complete.length) {
        const block = complete[0];
        next = guard(next.slice(0, block.index)) + block[0] + guard(next.slice(block.index + block[0].length));
      }
      if (next === raw) return;
      message.mes = next;
      if (repaired.changed) console.info('[艾迪娜 MVU] 已为合法 JSONPatch 数组补上漏写的 </JSONPatch>。');
      if (complete.length === 1 && openCount > complete.length) console.info('[艾迪娜 MVU] 已中和思维链中的伪 <UpdateVariable> 标签，保留唯一完整变量块。');
    } catch (err) {
      console.error('[艾迪娜 MVU] 伪变量标签中和失败:', err);
    }
  };
  const tryBind = () => {
    const scope = typeof eventOn === 'function' ? window : (window.parent && typeof window.parent.eventOn === 'function' ? window.parent : null);
    if (!(scope && typeof scope.eventOn === 'function')) return false;
    if (typeof tavern_events !== 'object' || !tavern_events || typeof tavern_events.MESSAGE_RECEIVED !== 'string') return false;
    if (typeof scope.eventMakeFirst === 'function') scope.eventMakeFirst(tavern_events.MESSAGE_RECEIVED, sanitize);
    else scope.eventOn(tavern_events.MESSAGE_RECEIVED, sanitize);
    return true;
  };
  const timer = setInterval(() => { if (tryBind()) clearInterval(timer); }, 1000);
})();

// --- 关系名册旧档迁移与维护（架构 v3：索引数组 → 名字键字典；字典期做键规整） ---
// 只在加载/切会话的静默时机跑（VARIABLE_INITIALIZED / CHAT_CHANGED），不在每轮更新后跑，
// 避免 replaceMvuData 直写与正在进行的变量更新竞争。仅在名册形态需要改变时写回；直写不触发事件链，天然无循环。
(function bindRosterMaintain() {
  let fixing = false;
  const maintainOnce = (api) => {
    if (fixing) return;
    let snapshot;
    try { snapshot = api.getMvuData({ type: 'message', message_id: 'latest' }); } catch (_) { return; }
    if (!snapshot || !snapshot.stat_data) return;
    const roster = snapshot.stat_data.关系 && snapshot.stat_data.关系.名册;
    let next = null;
    try {
      if (Array.isArray(roster)) {
        next = edinaMigrateRoster(roster); // 旧档：数组 → 名字键字典
      } else if (roster && typeof roster === 'object') {
        next = edinaNormalizeRosterAfterUpdate(roster, roster).roster; // 字典：键=名字等静态规整
      } else {
        return;
      }
    } catch (err) { console.error('[艾迪娜名册] 迁移计算失败:', err); return; }
    if (JSON.stringify(roster) === JSON.stringify(next)) return;
    fixing = true;
    (async () => {
      try {
        const nextData = JSON.parse(JSON.stringify(snapshot));
        nextData.stat_data.关系.名册 = next;
        // 世界书脏数据兼容写回：唯一允许的 replaceMvuData 直写点（直写不触发事件链，避免与变量更新竞争）
        /* WORLDBOOK-WRITE-BEGIN */
        await api.replaceMvuData(nextData, { type: 'message', message_id: 'latest' });
        /* WORLDBOOK-WRITE-END */
        console.info(Array.isArray(roster)
          ? '[艾迪娜名册] 旧档迁移完成：索引数组 → 名字键字典（' + Object.keys(next).filter((k) => k.charAt(0) !== '$').length + ' 人）'
          : '[艾迪娜名册] 名册静态规整完成');
      } catch (err) {
        console.error('[艾迪娜名册] 迁移写回失败:', err);
      } finally { fixing = false; }
    })();
  };
  const tryBind = () => {
    const scope = typeof eventOn === "function" ? window : (window.parent && typeof window.parent.eventOn === "function" ? window.parent : null);
    const api = window.Mvu || (window.parent && window.parent.Mvu);
    if (!(api && api.events && scope && typeof scope.eventOn === "function")) return false;
    const later = () => setTimeout(() => maintainOnce(api), 1200);
    scope.eventOn(api.events.VARIABLE_INITIALIZED, later);
    if (typeof tavern_events === "object" && tavern_events && typeof tavern_events.CHAT_CHANGED === "string") {
      scope.eventOn(tavern_events.CHAT_CHANGED, later);
    }
    // 绑定补跑（2026-09-21 真机实测）：重载场景下 CHAT_CHANGED 常在 Mvu 就绪前就已发完，
    // 此处注册必然错过；绑定成功后补跑两次（+2s/+8s）。幂等：名册已是字典且干净时不写回。
    setTimeout(() => maintainOnce(api), 2000);
    setTimeout(() => maintainOnce(api), 8000);
    return true;
  };
  const timer = setInterval(() => { if (tryBind()) clearInterval(timer); }, 1000);
})();

// --- 名册名字清单注入（BP-019 v3；名字键后模型不再数索引，但仍需知道册里现有谁） ---
// 每轮把当前名册的角色名清单以系统提示注入到生成上下文（depth 2，贴近最新楼层）：
// 更新已入册人物用 /关系/名册/<名字>/<字段>，名字必须与键完全一致；新角色才用 add /关系/名册/<角色名>。
(function bindRosterOrderInjector() {
