// --- 卡内 iframe 高度阻尼器 v2（BP-037，2026-10-01）：级联钳制，终止缩放环境改高战争 ---
// 根因（真机测量矩阵实锤，守则 82）：酒馆助手对消息 iframe 的高度写入有多个写入者，走 style 属性
// 整体改写通道（绕过一切 JS 属性访问器钩子），且测量源恒定相异——body.scrollHeight=805 与
// html.scrollHeight=806 在 dpr 1.25 下各自恒定，两个写入者逐帧对轰＝805/806 每帧交替＝整楼抖动。
// JS 侧拦截（v1 访问器）与写回（v2 草案）都无法终止常量源战争；唯一稳赢层＝CSS 级联：
// 作者样式表 `height: var(--edina-frame-h) !important` 压过写入者的普通内联声明——写入随便写，
// 计算布局恒定不动，可见抖动归零。钉住值由自愈线程每 300ms 按内容实测 max(scrollHeight) 收敛，
// 弹层展开/页签切换照常跟涨跟落。只作用卡自有 iframe（#edina-opening / #edina-hud-x）。
(async () => {
  const SCAN_MS = 800;
  const SETTLE_MS = 300;
  const PIN_CLASS = 'edina-height-pinned';
  const PIN_VAR = '--edina-frame-h';
  const armed = new WeakSet();

  const parentDoc = () => {
    try { return window.parent && window.parent.document ? window.parent.document : null; } catch (_) { return null; }
  };

  const ensureStyle = () => {
    try {
      const doc = parentDoc();
      if (!doc || doc.getElementById('edina-frame-pin-style')) return;
      const style = doc.createElement('style');
      style.id = 'edina-frame-pin-style';
      style.textContent = `.${PIN_CLASS} { height: var(${PIN_VAR}, 800px) !important; }`;
      doc.head.appendChild(style);
    } catch (_) {}
  };

  const isCardFrame = (frame) => {
    try {
      const doc = frame.contentDocument;
      return !!(doc && (doc.getElementById('edina-opening') || doc.getElementById('edina-hud-x')));
    } catch (_) { return false; }
  };

  const innerDesired = (frame) => {
    try {
      const idoc = frame.contentDocument;
      if (!idoc || !idoc.body) return 0;
      return Math.max(idoc.documentElement ? idoc.documentElement.scrollHeight : 0, idoc.body.scrollHeight);
    } catch (_) { return 0; }
  };

  const pin = (frame) => {
    if (armed.has(frame)) return;
    try {
      const wrapper = frame.parentElement;
      if (!wrapper) return;
      const desired = Math.max(parseFloat(frame.style.height) || 0, frame.getBoundingClientRect().height || 0, innerDesired(frame));
      if (desired < 1) return;
      frame.classList.add(PIN_CLASS);
      wrapper.style.setProperty(PIN_VAR, `${Math.ceil(desired)}px`);
      armed.add(frame);
    } catch (_) {}
  };

  const scan = () => {
    const doc = parentDoc();
    if (!doc) return;
    ensureStyle();
    try { doc.querySelectorAll('#chat iframe').forEach((frame) => { if (!armed.has(frame) && isCardFrame(frame)) pin(frame); }); } catch (_) {}
  };

  // 自愈：按内容实测高度收敛钉住值（弹层展开/页签切换/内容增删在 300ms 内跟涨跟落）
  const settle = () => {
    const doc = parentDoc();
    if (!doc) return;
    try {
      doc.querySelectorAll('iframe.' + PIN_CLASS).forEach((frame) => {
        const wrapper = frame.parentElement;
        if (!wrapper) return;
        const desired = innerDesired(frame);
        if (desired < 1) return;
        const current = parseFloat(wrapper.style.getPropertyValue(PIN_VAR)) || 0;
        if (Math.abs(Math.ceil(desired) - current) >= 1) {
          wrapper.style.setProperty(PIN_VAR, `${Math.ceil(desired)}px`);
        }
      });
    } catch (_) {}
  };

  setInterval(scan, SCAN_MS);
  setInterval(settle, SETTLE_MS);
  scan();
})();

