  template: z.any().optional(),
}).passthrough();

// 名册名字键归一（结构 v3，2026-09-26 驾驶员确认）：旧档把名册存成索引数组，
// 这里在 schema 解析前把数组转成「名字 → 人物对象」字典（无名丢弃、同名保最早）。
// 新结构下键即名字：模型更新路径写 /关系/名册/<名字>/<字段>，不再需要数索引。
function 名册归一(值) {
  if (!Array.isArray(值)) return 值;
  const out = {};
  值.forEach((条目) => {
    if (!条目 || typeof 条目 !== 'object' || Array.isArray(条目)) return;
    const 名字 = String(条目['名字'] || '').trim();
    if (!名字 || out[名字]) return;
    out[名字] = 条目;
  });
  return out;
}

// 技能名字键归一（BP-035，2026-09-30 驾驶员确认）：旧档把技能存成索引数组，
// 这里在 schema 解析前把数组转成「名称 → 技能对象」字典（无名丢弃、纯名字串保名、同名保最早）。
// 新结构下键即名称：模型更新路径写 /技能/<名称>/<字段>，不再需要数索引。
function 技能归一(值) {
  if (!Array.isArray(值)) return 值;
  const out = {};
  值.forEach((条目) => {
    if (typeof 条目 === 'string') {
      const 名字 = 条目.trim();
      if (名字 && !out[名字]) out[名字] = { 名称: 名字 };
      return;
    }
    if (!条目 || typeof 条目 !== 'object' || Array.isArray(条目)) return;
    const 名字 = String(条目['名称'] || '').trim();
    if (!名字 || out[名字]) return;
    out[名字] = 条目;
  });
  return out;
}

